package com.turboio.addon;

import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.zip.*;

/** Streaming derived export from verified local or remote copies. Sealed
 * original journals stay untouched; output uses a user-selected destination. */
final class LifelogAudioExport {
 interface Decoder extends AutoCloseable {void validate(byte[] packet,int samples48)throws IOException;void close()throws IOException;}
 interface Decoders {Decoder open()throws IOException;}
 static final long MAX_BYTES=536870912,TTL=3600000;
 static final class Draft {final String id,account,title,sha;final long size,frames,samples,parts,created;final File file;Draft(File directory,Map<String,Object> data)throws IOException{id=directory.getName();account=(String)data.get("account");title=(String)data.get("title");sha=(String)data.get("sha256");size=LifelogAudioLibrary.number(data,"bytes");frames=LifelogAudioLibrary.number(data,"frames");samples=LifelogAudioLibrary.number(data,"samples48");parts=LifelogAudioLibrary.number(data,"parts");created=LifelogAudioLibrary.number(data,"created_at");file=new File(directory,"audio.zip");require(account!=null&&account.matches("[a-f0-9]{64}")&&sha!=null&&sha.matches("[a-f0-9]{64}")&&"智记原音片段.zip".equals(title)&&size>0&&size<=MAX_BYTES&&frames>0&&parts>0,"AUDIO_EXPORT_DRAFT");}}
 private static void require(boolean value,String code)throws IOException{LifelogAudioLibrary.require(value,code);}
 private static File base(File cache)throws IOException{File root=cache.getCanonicalFile();File base=new File(root,"lifelog-audio-exports");require(root.isDirectory()&&!Files.isSymbolicLink(cache.toPath()),"AUDIO_EXPORT_PATH");if(!base.exists())require(base.mkdir(),"AUDIO_EXPORT_DIRECTORY");safe(base);return base;}
 private static void safe(File path)throws IOException{require(!Files.isSymbolicLink(path.toPath())&&path.getAbsoluteFile().equals(path.getCanonicalFile()),"AUDIO_EXPORT_PATH");}
 static String sha(File file)throws IOException{try{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)digest.update(b,0,n);}StringBuilder out=new StringBuilder();for(byte b:digest.digest())out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
 static Draft prepare(File files,File cache,String account,String material,List<Object> sessions,List<Object> archives,Decoders decoders,LifelogAudioArchive.Guard guard,long now)throws IOException{
  return prepareSources(cache,account,material,LifelogAudioSource.local(files,account,material,sessions,archives,guard),decoders,guard,now);
 }
 private static final class Part {final Map<String,Object> proof,index;final LifelogAudioSource.Summary summary;Part(Map<String,Object> proof,Map<String,Object> index,LifelogAudioSource.Summary summary){this.proof=proof;this.index=index;this.summary=summary;}}
 private static void origin(Map<String,Object> part,Map<String,Object> origin){if(part==null)return;List<Object> origins=WireJson.list(part.get("origins"));for(Object old:origins)if(Arrays.equals(WireJson.bytes(old),WireJson.bytes(origin)))return;origins.add(origin);}
 private static void current(List<LifelogAudioSource> sources,LifelogAudioArchive.Guard guard)throws IOException{guard.check();for(LifelogAudioSource source:sources)source.current(guard);}
 static Draft prepareSources(File cache,String account,String material,List<LifelogAudioSource> inputs,Decoders decoders,LifelogAudioArchive.Guard guard,long now)throws IOException{
  guard.check();require(account!=null&&account.matches("[a-f0-9]{64}")&&material!=null&&material.matches("rayneo-lifelog-[a-f0-9]{64}")&&inputs!=null&&!inputs.isEmpty()&&inputs.size()<=512&&decoders!=null,"AUDIO_EXPORT_CONTEXT");List<LifelogAudioSource> sources=new ArrayList<>(inputs);for(LifelogAudioSource source:sources)require(source!=null&&account.equals(source.account)&&material.equals(source.material),"AUDIO_EXPORT_PROVENANCE");current(sources,guard);
  File base=base(cache);File[] prior=base.listFiles();require(prior!=null,"AUDIO_EXPORT_PATH");for(File item:prior){safe(item);require(item.getName().matches("[a-f0-9]{32}")&&item.isDirectory(),"AUDIO_EXPORT_PATH");if(now-item.lastModified()>TTL)remove(cache,item.getName());}prior=base.listFiles();require(prior!=null&&prior.length<2,"AUDIO_EXPORT_BUSY");
  String id=UUID.randomUUID().toString().replace("-","");File directory=new File(base,id);require(directory.mkdir(),"AUDIO_EXPORT_DIRECTORY");File target=new File(directory,"audio.zip");long[] totals={0,0,0,0,Long.MAX_VALUE,0,0,0};List<Object> manifest=new ArrayList<>();Map<String,Part> seen=new LinkedHashMap<>();boolean success=false;boolean[] remote={false};
  try{try(FileOutputStream disk=new FileOutputStream(target);BufferedOutputStream buffer=new BufferedOutputStream(disk,65536);ZipOutputStream zip=new ZipOutputStream(buffer,StandardCharsets.UTF_8)){
   zip.setLevel(0);for(LifelogAudioSource source:sources){source.current(guard);Map<String,Object> proof=source.proof();Part previous=seen.get(source.identity());final boolean duplicate=previous!=null;require(!duplicate||Arrays.equals(WireJson.bytes(previous.proof),WireJson.bytes(proof)),"AUDIO_EXPORT_PROVENANCE");require(duplicate||seen.size()<256,"AUDIO_EXPORT_BUDGET");
    final OpusFile[] mux={null};final Decoder[] decoder={null};long[] count={0,0};String name=String.format(Locale.ROOT,"片段-%03d.opus",totals[2]+1);LifelogAudioSource.Summary summary;
    try{summary=source.visit((frames,received)->{for(AlwaysOnAudioBatch.Frame frame:frames){source.current(guard);byte[] packet=frame.bytes();try{require(++totals[6]<=5000000,"AUDIO_EXPORT_BUDGET");int samples=OpusFile.samples48(packet);if(decoder[0]==null)decoder[0]=decoders.open();decoder[0].validate(packet,samples);count[0]++;count[1]+=samples;
      if(!duplicate){if(mux[0]==null){zip.putNextEntry(new ZipEntry(name));mux[0]=new OpusFile(zip,(int)Long.parseLong(source.stream.substring(0,8),16));}require(totals[0]<5000000&&target.length()<MAX_BYTES-65536&&directory.getUsableSpace()>67108864,"AUDIO_EXPORT_BUDGET");mux[0].packet(packet);totals[0]++;totals[1]+=samples;}
     }finally{Arrays.fill(packet,(byte)0);}}},guard);
     require(summary.frames==count[0]&&summary.samples==count[1],"AUDIO_EXPORT_PROVENANCE");
     if(duplicate){LifelogAudioSource.Summary old=previous.summary;require(summary.frames==old.frames&&summary.samples==old.samples&&summary.skipped==old.skipped&&summary.controls==old.controls&&summary.first==old.first&&summary.last==old.last,"AUDIO_EXPORT_PROVENANCE");origin(previous.index,source.origin());}
     else{Map<String,Object> index=null;if(mux[0]!=null){mux[0].finish();zip.closeEntry();totals[2]++;index=WireJson.object("file",name,"frames",count[0],"samples48",count[1],"recording_complete",false,"source_chain_sha256",proof.get("chain"),"source_batches",proof.get("count"),"control_batches",summary.controls,"origins",new ArrayList<>());origin(index,source.origin());manifest.add(index);}seen.put(source.identity(),new Part(proof,index,summary));totals[3]+=summary.skipped;totals[7]+=summary.controls;if(summary.frames>0){totals[4]=Math.min(totals[4],summary.first);totals[5]=Math.max(totals[5],summary.last);}}
     if("server".equals(source.origin().get("location")))remote[0]=true;
    }finally{if(decoder[0]!=null)decoder[0].close();}
   }
   current(sources,guard);require(totals[0]>0,"AUDIO_EXPORT_NO_FRAMES");String note="智记原音片段\n\n只包含已收到并成功保存的音频；可能从智记中途开始。\n每个文件是独立保存的片段，按所选来源的接收顺序导出；完全相同且已核验的片段只保留一份。\n断连或未收到的部分不会补成静音，也不代表完整全天录音。\n已核验的退出控制记录："+totals[7]+"；不计入音频帧，也不代表完整录音。\n未解析的非 A3 批次："+totals[3]+"。原始数据继续保留在来源中。\n"+(remote[0]?"本次包含已核验的服务器副本。服务器每份原音的三天到期时间保持原回执，导出不会续期；已保存到手机的导出文件不会随服务器到期删除。\n":"本次读取手机本地副本；是否已有远程备份，请查看原音备份状态。\n");
   zip.putNextEntry(new ZipEntry("说明.txt"));zip.write(note.getBytes(StandardCharsets.UTF_8));zip.closeEntry();zip.putNextEntry(new ZipEntry("片段索引.json"));zip.write(WireJson.bytes(WireJson.object("schema",1,"parts",manifest,"first_received_at",totals[4],"last_received_at",totals[5],"source_link_verified",true,"recording_complete",false,"remote_stored",remote[0],"export_uses_remote",remote[0],"control_batches",totals[7])));zip.closeEntry();zip.finish();zip.flush();buffer.flush();disk.getFD().sync();
  }
  current(sources,guard);require(target.length()>0&&target.length()<=MAX_BYTES,"AUDIO_EXPORT_BUDGET");Map<String,Object> receipt=WireJson.object("schema",1,"account",account,"title","智记原音片段.zip","sha256",sha(target),"bytes",target.length(),"frames",totals[0],"samples48",totals[1],"parts",totals[2],"created_at",now);try(AtomicDocument state=new AtomicDocument(new File(directory,"draft.json"),8192)){state.save(receipt);}Draft draft=new Draft(directory,receipt);current(sources,guard);success=true;return draft;
  }finally{if(!success)remove(cache,id);}
 }
 static Draft load(File cache,String id,String account,long now)throws IOException{require(id!=null&&id.matches("[a-f0-9]{32}"),"AUDIO_EXPORT_DRAFT");File directory=new File(base(cache),id);safe(directory);File state=new File(directory,"draft.json");safe(state);require(state.isFile()&&state.length()<=8192,"AUDIO_EXPORT_DRAFT");Draft draft=new Draft(directory,WireJson.map(WireJson.read(Files.readAllBytes(state.toPath()))));safe(draft.file);require(account.equals(draft.account)&&now>=draft.created&&now-draft.created<=TTL&&draft.file.isFile()&&draft.file.length()==draft.size,"AUDIO_EXPORT_DRAFT");return draft;}
 static void copy(Draft draft,OutputStream out,LifelogAudioArchive.Guard guard)throws IOException{guard.check();safe(draft.file);require(draft.file.length()==draft.size&&draft.sha.equals(sha(draft.file)),"AUDIO_EXPORT_CHANGED");try(InputStream in=new FileInputStream(draft.file)){byte[] b=new byte[65536];int n;long total=0;while((n=in.read(b))!=-1){guard.check();total+=n;require(total<=draft.size,"AUDIO_EXPORT_CHANGED");out.write(b,0,n);}require(total==draft.size,"AUDIO_EXPORT_CHANGED");}out.flush();guard.check();}
 static void remove(File cache,String id)throws IOException{require(id!=null&&id.matches("[a-f0-9]{32}"),"AUDIO_EXPORT_DRAFT");File directory=new File(base(cache),id);safe(directory);if(!directory.exists())return;File[] list=directory.listFiles();require(list!=null&&list.length<=7,"AUDIO_EXPORT_PATH");for(File file:list){safe(file);require(Arrays.asList("audio.zip","draft.json","draft.json.partial","draft.json.lock","remote.json","remote.json.partial","remote.json.lock").contains(file.getName())&&file.isFile(),"AUDIO_EXPORT_PATH");}for(File file:list)Files.delete(file.toPath());Files.delete(directory.toPath());}
}
